# Disposable local accounts only; no outbound email, all recovery links generated by local Auth admin.
import json,urllib.request,urllib.error,pathlib,secrets,subprocess
K=json.loads(pathlib.Path('.local-stack/keys.json').read_text());base='http://127.0.0.1:54324';count=0

def request(path,body=None,token=None,method='POST'):
 headers={'Content-Type':'application/json','apikey':K['anon'],'Authorization':'Bearer '+(token or K['anon'])}
 req=urllib.request.Request(base+path,data=None if body is None else json.dumps(body).encode(),headers=headers,method=method)
 try:
  with urllib.request.urlopen(req,timeout=20) as r:status=r.status;raw=r.read().decode()
 except urllib.error.HTTPError as e:status=e.code;raw=e.read().decode()
 try:return status,json.loads(raw) if raw else None
 except:return status,raw

def ok(label,condition):
 global count
 assert condition,label
 count+=1;print('PASS',label,flush=True)
def sql(query):subprocess.run(['sudo','docker','exec','-i','kdial-db','psql','-U','postgres','-v','ON_ERROR_STOP=1','-c',query],check=True,stdout=subprocess.DEVNULL)
email='recovery-'+secrets.token_hex(5)+'@example.invalid';old=secrets.token_urlsafe(24);new=secrets.token_urlsafe(24)
s,d=request('/auth/v1/admin/users',{'email':email,'password':old,'email_confirm':True},K['service_role']);ok('local Auth creates disposable recovery account',s==200);uid=d['id']
sql("insert into kdial_private.admin_roles values ('%s','editor',now())"%uid)
s,d=request('/auth/v1/token?grant_type=password',{'email':email,'password':old});ok('initial account login',s==200);jwt=d['access_token'];refresh=d['refresh_token']
s,d=request('/auth/v1/admin/generate_link',{'type':'recovery','email':email},K['service_role']);ok('local recovery link generated without SMTP/email delivery',s==200 and 'hashed_token' in d);hashed=d['hashed_token']
s,d=request('/auth/v1/verify',{'type':'recovery','token_hash':hashed});ok('recovery token establishes Auth session',s==200 and 'access_token' in d);recoveryjwt=d['access_token']
s,d=request('/auth/v1/verify',{'type':'recovery','token_hash':hashed});ok('recovery token cannot be reused',s>=400)
s,d=request('/auth/v1/user',{'password':new},recoveryjwt,method='PUT');ok('recovered session changes password',s==200)
s,d=request('/auth/v1/token?grant_type=password',{'email':email,'password':old});ok('old password rejected',s>=400)
s,d=request('/auth/v1/token?grant_type=password',{'email':email,'password':new});ok('new password accepted',s==200);sessionjwt=d['access_token'];sessionrefresh=d['refresh_token']
s,d=request('/rest/v1/rpc/kdial_admin_state',{},sessionjwt);ok('recovered user still needs live server role',s==200 and d['role']=='editor')
s,d=request('/auth/v1/token?grant_type=refresh_token',{'refresh_token':sessionrefresh});ok('real Auth refresh succeeds',s==200);sessionjwt=d['access_token'];sessionrefresh=d['refresh_token']
s,d=request('/auth/v1/logout?scope=global',None,sessionjwt);ok('global logout accepted by Auth',s==204)
s,d=request('/auth/v1/token?grant_type=refresh_token',{'refresh_token':sessionrefresh});ok('logged-out refresh token rejected',s>=400)
s,d=request('/rest/v1/rpc/kdial_admin_state',{},sessionjwt);ok('observed documented JWT lifetime: PostgREST accepts unexpired signed access token after logout',s==200)
sql("delete from kdial_private.admin_roles where user_id='%s'"%uid)
s,d=request('/rest/v1/rpc/kdial_admin_state',{},sessionjwt);ok('role removal immediately denies even an unexpired issued JWT',s==403)
print('TOTAL',count,'real local recovery/session/role assertions. SMTP delivery/invite browser path remain hosted release gates. Access JWT remains valid until expiry; emergency access revocation removes admin role.',flush=True)
